<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Task;
use App\Models\CalendarEvent;
use App\Models\PlanningTemplate;
use App\Models\Workspace;
use App\Services\Identity;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Tests\TestCase;
class CalendarTest extends TestCase {
 use RefreshDatabase;
 private function login(User $u): static{return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version])->withoutVite();}
 private function payload(array $extra=[]): array{return array_merge(['title'=>'Focus block','kind'=>'focus','starts_at'=>'2026-11-27T09:00','ends_at'=>'2026-11-27T10:00'],$extra);}
 private function event(User $u,array $extra=[]): CalendarEvent{$w=Identity::personal($u);$e=new CalendarEvent(array_merge(['title'=>'Private appointment','kind'=>'meeting','starts_at'=>'2026-11-27 03:00:00','ends_at'=>'2026-11-27 04:00:00','timezone'=>'Asia/Dhaka','repeat_count'=>1],$extra));$e->workspace_id=$w->id;$e->creator_id=$u->id;$e->save();return $e;}
 private function task(User $u): Task{$t=new Task(['title'=>'Study DevOps','status'=>'pending','priority'=>'medium','planned_date'=>'2026-11-27']);$t->workspace_id=Identity::personal($u)->id;$t->creator_id=$u->id;$t->save();return $t;}
 private function templatePayload(): array{return ['name'=>'Workday','blocks'=>[['title'=>'Morning focus','start'=>'09:00','end'=>'10:00','kind'=>'focus'],['title'=>'Break','start'=>'10:00','end'=>'10:30','kind'=>'break']]];}
 public function test_guest_denied(): void{$this->get('/calendar')->assertRedirect('/login');}
 public function test_calendar_crud_and_timezone(): void{$u=User::factory()->create(['timezone'=>'Asia/Dhaka']);$this->login($u)->post('/calendar',$this->payload())->assertRedirect();$e=CalendarEvent::firstOrFail();$this->assertSame('2026-11-27 03:00:00',$e->starts_at->format('Y-m-d H:i:s'));$this->get('/calendar/'.$e->id.'/edit')->assertOk()->assertSee('Focus block');$this->put('/calendar/'.$e->id,$this->payload(['title'=>'Updated block']))->assertRedirect();$this->assertSame('Updated block',$e->fresh()->title);$this->delete('/calendar/'.$e->id)->assertRedirect();$this->assertDatabaseMissing('calendar_events',['id'=>$e->id]);}
 public function test_day_week_month_and_dashboard_show_events_and_tasks(): void{$u=User::factory()->create(['timezone'=>'Asia/Dhaka']);$this->event($u);$this->task($u);$this->travelTo(\Illuminate\Support\Carbon::parse('2026-11-27 01:00 UTC'));$this->login($u);foreach(['day','week','month'] as $v)$this->get('/calendar?date=2026-11-27&view='.$v)->assertOk()->assertSee('Private appointment')->assertSee('Study DevOps');$this->get('/dashboard')->assertOk()->assertSee('Private appointment');$this->get('/calendar/create')->assertOk();}
 public function test_foreign_event_and_forged_membership_denied(): void{$u=User::factory()->create();$other=User::factory()->create();$e=$this->event($other);Identity::personal($other)->members()->attach($u->id,['role'=>'admin']);$this->login($u)->get('/calendar?date=2026-11-27')->assertOk()->assertDontSee('Private appointment');$this->get('/calendar/'.$e->id.'/edit')->assertNotFound();$this->put('/calendar/'.$e->id,$this->payload())->assertNotFound();$this->post('/calendar/'.$e->id.'/move',['date'=>'2026-11-28'])->assertNotFound();$this->delete('/calendar/'.$e->id)->assertNotFound();}
 public function test_business_workspace_denied(): void{$u=User::factory()->create();$w=Workspace::create(['owner_id'=>$u->id,'name'=>'Business','type'=>'business']);$this->login($u)->withSession(['workspace_id'=>$w->id])->get('/calendar')->assertForbidden();}
 public function test_task_link_is_scoped(): void{$u=User::factory()->create();$other=User::factory()->create();$t=$this->task($other);$this->login($u)->post('/calendar',$this->payload(['kind'=>'task','task_id'=>$t->id]))->assertSessionHasErrors('task_id');$own=$this->task($u);$this->post('/calendar',$this->payload(['kind'=>'task','task_id'=>$own->id]))->assertRedirect();$this->assertDatabaseHas('calendar_events',['task_id'=>$own->id]);}
 public function test_conflicts_and_invalid_intervals(): void{$u=User::factory()->create(['timezone'=>'Asia/Dhaka']);$this->event($u);$this->login($u)->post('/calendar',$this->payload())->assertSessionHasErrors('starts_at');$this->post('/calendar',$this->payload(['starts_at'=>'2026-11-27T11:00','ends_at'=>'2026-11-27T10:00']))->assertSessionHasErrors('ends_at');$this->post('/calendar',$this->payload(['starts_at'=>'2026-11-27T10:00','ends_at'=>'2026-11-27T11:00']))->assertRedirect();$this->assertSame(2,CalendarEvent::count());}
 public function test_repeating_events_and_future_conflict(): void{$u=User::factory()->create(['timezone'=>'Asia/Dhaka']);$this->login($u)->post('/calendar',$this->payload(['recurrence'=>'weekly','repeat_count'=>3]))->assertRedirect();$this->get('/calendar?date=2026-12-04&view=day')->assertOk()->assertSee('Focus block');$this->post('/calendar',$this->payload(['starts_at'=>'2026-12-04T09:30','ends_at'=>'2026-12-04T10:30']))->assertSessionHasErrors('starts_at');$this->assertSame(1,CalendarEvent::count());}
 public function test_drag_move_preserves_duration(): void{$u=User::factory()->create(['timezone'=>'Asia/Dhaka']);$e=$this->event($u);$this->login($u)->post('/calendar/'.$e->id.'/move',['date'=>'2026-11-28'])->assertRedirect();$this->assertSame('2026-11-28 03:00:00',$e->fresh()->starts_at->format('Y-m-d H:i:s'));$this->assertSame('2026-11-28 04:00:00',$e->fresh()->ends_at->format('Y-m-d H:i:s'));}
 public function test_template_application_is_atomic_and_idempotent(): void{$u=User::factory()->create(['timezone'=>'Asia/Dhaka']);$this->login($u)->post('/calendar/templates',$this->templatePayload())->assertRedirect();$t=PlanningTemplate::firstOrFail();$this->get('/calendar/templates')->assertOk()->assertSee('Workday');$this->post('/calendar/templates/'.$t->id.'/apply',['date'=>'2026-11-27'])->assertRedirect();$this->assertSame(2,CalendarEvent::count());$this->post('/calendar/templates/'.$t->id.'/apply',['date'=>'2026-11-27'])->assertSessionHasErrors('date');$this->assertSame(2,CalendarEvent::count());$this->event($u,['starts_at'=>'2026-11-28 04:00:00','ends_at'=>'2026-11-28 04:30:00']);$this->post('/calendar/templates/'.$t->id.'/apply',['date'=>'2026-11-28'])->assertSessionHasErrors('starts_at');$this->assertSame(3,CalendarEvent::count());$this->assertSame(1,DB::table('calendar_template_applications')->count());}
 public function test_foreign_template_is_not_visible_or_applicable(): void{$u=User::factory()->create();$other=User::factory()->create();$t=new PlanningTemplate($this->templatePayload());$t->workspace_id=Identity::personal($other)->id;$t->save();$this->login($u)->get('/calendar/templates')->assertOk()->assertDontSee('Workday');$this->post('/calendar/templates/'.$t->id.'/apply',['date'=>'2026-11-27'])->assertNotFound();$this->delete('/calendar/templates/'.$t->id)->assertNotFound();}
}
